import{_ as t,o as n,c as r,ag as e}from"./chunks/framework.D5hoimZQ.js";const y=JSON.parse('{"title":"科学日报 · 2026-11-07（能源 · 氢与氢基衍生物的中国碳中和路径）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/wind-energy/science-daily-2026-11-07-hydrogen.md","filePath":"topics/wind-energy/science-daily-2026-11-07-hydrogen.md"}'),s={name:"topics/wind-energy/science-daily-2026-11-07-hydrogen.md"};function i(l,o,g,c,a,d){return n(),r("div",null,[...o[0]||(o[0]=[e('<h1 id="科学日报-·-2026-11-07-能源-·-氢与氢基衍生物的中国碳中和路径" tabindex="-1">科学日报 · 2026-11-07（能源 · 氢与氢基衍生物的中国碳中和路径） <a class="header-anchor" href="#科学日报-·-2026-11-07-能源-·-氢与氢基衍生物的中国碳中和路径" aria-label="Permalink to &quot;科学日报 · 2026-11-07（能源 · 氢与氢基衍生物的中国碳中和路径）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-07.md</code> — 第57期 ｜ 科学板块（能源向 1 篇） 落盘说明：文件名带 <code>-hydrogen</code> 后缀，避免与其它主题同日同名文件互引产生伪边。</p></blockquote><hr><h2 id="科学日报-2026-11-07-能源-1-1-氢不是「补充」-是省下-10-7-万亿美元的路线选择" tabindex="-1">科学日报 2026-11-07（能源 1/1）：氢不是「补充」，是省下 10.7 万亿美元的路线选择 <a class="header-anchor" href="#科学日报-2026-11-07-能源-1-1-氢不是「补充」-是省下-10-7-万亿美元的路线选择" aria-label="Permalink to &quot;科学日报 2026-11-07（能源 1/1）：氢不是「补充」，是省下 10.7 万亿美元的路线选择&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-07.md</code> ｜ DOI: 10.1038/s41586-026-11351-4 ｜ Nature (2026)</p></blockquote><ul><li>问题：中国是<strong>最大 CO₂ 排放国</strong>，同时卡在两头：<strong>波动性可再生能源消纳</strong> 与 <strong>难减排部门（重工、航运、化工）脱碳</strong>。氢被当作连接两者的绿色载体，但<strong>运输、储存、燃料电池采用</strong>成本高，导致「<strong>经济可行的氢部署方案</strong>」长期含糊。到底该「先电气化、氢补残局」，还是「氢与电并行」？</li><li>方法（四层精度，这是本文的可信度来源）： <ol><li><strong>高分辨率可再生资源布局</strong>（风光选址到格点级）；</li><li><strong>29 个省级区域逐时电力系统运行</strong>（不是年度电量平衡，是 8760 小时调度）；</li><li><strong>超过 46,000 条铁路 / 公路 / 海运 / 管道</strong>的氢衍生物（氨、甲醇等）<strong>转运路线</strong>；</li><li><strong>全终端部门工艺级燃料替代策略</strong>（钢铁、水泥、化工、交通逐工艺判断能不能换氢）。</li></ol></li><li>结果（实测）： <ul><li>纳入<strong>氢与氢基衍生物</strong>，相比「可再生 + 电气化」路径，<strong>总转型成本低 10.7 万亿美元</strong>；</li><li>实现<strong>负减排成本 −6.15 美元/吨</strong>（即减排本身净省钱）；</li><li><strong>消除石油进口支出</strong>，规模相当于 <strong>2023 年中国贸易顺差的 50% 以上</strong>；</li><li>同时<strong>提升就业与经济增长</strong>。</li></ul></li><li>洞察（对本库 <code>wind-energy</code> × <code>energysim</code> × <code>economic-cycles</code>）： <ol><li><strong>「消纳问题」在模型里被重新定义成「运输问题」</strong>——真正贵的不是发电，而是把能量<strong>搬到用不掉的地方</strong>；氢衍生物的价值 = <strong>把电变成可运输的化学品</strong>（与储运基础设施耦合的 46,000 条路线才是主变量）。判据：<strong>评价任何&quot;高比例可再生&quot;情景，先看它的输运网络建模粒度</strong>。</li><li><strong>与 <code>wind-energy</code> 既有主线（功率预测 / AEP / 尾流）互补</strong>：那些工作优化的是<strong>供给侧的单位成本</strong>，这篇指出<strong>系统侧（逐时运行 + 输运 + 工艺替代）才是 10 万亿美元量级的杠杆</strong>——单机效率再提 1% 抵不过网络层 1% 的配置改善。</li><li><strong>负减排成本 = 政策语言里的强论据</strong>：−6.15 美元/吨意味着「不做的成本更高」，这比「未来会更便宜」的学习曲线论证更适合写进规划；同时也提醒：<strong>这类结论高度依赖化石能源价格假设</strong>，做决策时应做价格情景敏感性（原文给的是路径对比而非点估计）。</li></ol></li></ul><hr><blockquote><p>关键词：氢、绿氢、氢基衍生物、氨、甲醇、碳中和、能源转型、可再生消纳、逐时调度、输运网络、管道、海运、工艺替代、负减排成本、石油进口、省级电力系统、风光、弃风弃光、energysim、科学日报第57期、改路径优于加力度</p></blockquote>',8)])])}const _=t(s,[["render",i]]);export{y as __pageData,_ as default};
